urlset:
{{ home_url }}
{% for static_url in static_urls %}{{ static_url }}{% endfor %}
{% for category in categories %}{% url 'core:category_storefront' category.slug as category_path %}{{ request.scheme }}://{{ request.get_host }}{{ category_path }}{% endfor %}
{% for product in products %}{% url 'core:product_detail' product.slug as product_path %}{{ request.scheme }}://{{ request.get_host }}{{ product_path }}{{ product.updated_at|date:'Y-m-d' }}{% if product.image %}{{ product.image.url }}{{ product.name }}{% endif %}{% endfor %}
